/**
 * Group model
 *
 * The server does NOT know the group key: it is generated by the creator and
 * distributed encrypted (one envelope per member, under each member's
 * pairwise key). Here we only track members and whether the current key has
 * been distributed.
 */

class Group {
    constructor(name, creator) {
        this.name = name;
        this.creator = creator;
        this.members = new Set([creator]);
        this.createdAt = new Date();
        this.keyDistributedAt = null; // When the creator distributed the current key
        this.isActive = true;
    }

    /**
     * Adds a member (the current key is no longer valid: a re-key follows)
     */
    addMember(username) {
        this.members.add(username);
        this.invalidateKey();
    }

    /**
     * Removes a member (the current key is no longer valid: a re-key follows).
     * If the creator leaves, the role passes to another member.
     */
    removeMember(username) {
        this.members.delete(username);
        this.invalidateKey();

        if (this.creator === username && this.members.size > 0) {
            this.creator = Array.from(this.members)[0];
        }
    }

    invalidateKey() {
        this.keyDistributedAt = null;
    }

    markKeyDistributed() {
        this.keyDistributedAt = new Date();
    }

    isMember(username) {
        return this.members.has(username);
    }

    getInfo() {
        return {
            name: this.name,
            creator: this.creator,
            members: Array.from(this.members),
            memberCount: this.members.size,
            createdAt: this.createdAt,
            keysEstablished: !!this.keyDistributedAt,
            isActive: this.isActive
        };
    }
}

module.exports = Group;
